// Checks the incoming request. Budget, pause switch and instructions come from the ai_clients table in the next steps.
const body = $('Client request').first().json.body ?? {};
const s = $('Settings').first().json;
const clientId = String(body.client_id ?? '').trim();
const prompt = String(body.prompt ?? '');

let error = null;
if (!/^[A-Za-z0-9._:@-]{1,100}$/.test(clientId)) error = 'client_id is missing or contains characters other than letters, digits and . _ : @ -';
else if (!prompt.trim()) error = 'prompt is missing';
else if (prompt.length > Number(s.max_prompt_chars)) error = `prompt is longer than ${s.max_prompt_chars} characters`;
else if (!(Number(s.max_output_tokens) > 0) || !(Number(s.max_iterations) > 0)) error = 'Settings: max_output_tokens and max_iterations must be positive numbers';

return [{
  json: {
    valid: error === null,
    error,
    client_id: clientId,
    prompt,
    period: new Date().toISOString().slice(0, 7), // calendar month in UTC, e.g. 2026-10
    run_id: String($execution.id),
  },
}];

// Decides whether this run may start and how much budget to reserve for it.
const req = $('Validate request').first().json;
const s = $('Settings').first().json;
const client = $('Look up client').first().json ?? {};
const rows = $('Load month ledger').all().map((i) => i.json).filter((r) => r.status);

const round = (n) => Math.round(n * 1e6) / 1e6;
const rateIn = Number(s.input_cost_per_1m_tokens) || 0;
const rateOut = Number(s.output_cost_per_1m_tokens) || 0;
const useCost = rateIn > 0 || rateOut > 0;
const amountFor = (tokensIn, tokensOut) => round(useCost ? (tokensIn * rateIn + tokensOut * rateOut) / 1e6 : tokensIn + tokensOut);

// Everything except released rows counts: settled runs, open reservations and expired reservations.
const used = round(rows.filter((r) => r.status !== 'released').reduce((sum, r) => sum + (Number(r.amount) || 0), 0));

// Worst case for one run: each iteration resends the prompt plus earlier output and may write max_output_tokens.
const instructions = String(client.instructions ?? '');
const maxOut = Number(s.max_output_tokens);
const iterations = Number(s.max_iterations);
const promptTokens = Math.ceil((String(s.system_message ?? '').length + instructions.length + req.prompt.length) / 4) + (Number(s.tool_overhead_tokens) || 0);
const estIn = iterations * promptTokens + (maxOut * iterations * (iterations - 1)) / 2;
const estOut = iterations * maxOut;
const reservation = amountFor(estIn, estOut);

const rawBudget = client.monthly_budget;
const budget = Number(rawBudget);
const paused = client.paused === true || String(client.paused).toLowerCase() === 'true';

let httpStatus = 200;
let error = null;
let message = null;
if (!client.client_id) {
  httpStatus = 403; error = 'unknown_client'; message = 'This client_id is not in the ai_clients table.';
} else if (paused) {
  httpStatus = 403; error = 'client_paused'; message = 'AI runs are paused for this client.';
} else if (rawBudget === null || rawBudget === undefined || rawBudget === '' || !Number.isFinite(budget) || budget < 0) {
  httpStatus = 503; error = 'budget_not_configured'; message = 'No valid monthly_budget is set for this client, so the run is refused.';
} else if (used + reservation > budget) {
  httpStatus = 429; error = 'budget_reached'; message = 'Not enough budget left this month for another run.';
}

return [{
  json: {
    ...req,
    allowed: httpStatus === 200,
    http_status: httpStatus,
    error,
    message,
    unit: useCost ? 'cost' : 'tokens',
    budget,
    used_before: used,
    reservation,
    instructions,
    row: {
      client_id: req.client_id,
      period: req.period,
      run_id: req.run_id,
      status: 'reserved',
      amount: reservation,
      tokens_in: 0,
      tokens_out: 0,
      model_calls: 0,
      note: 'Reserved before the run',
    },
  },
}];

// Re-reads the ledger after our reservation was written.
// Counts settled and expired rows, plus open reservations that were written BEFORE ours (lower id).
// The earliest reservations win; a later run that would overspend backs off.
const c = $('Check budget').first().json;
const mine = $('Reserve budget').first().json;
if (mine.id === undefined) throw new Error('The reservation row was not returned by the Data table');

const round = (n) => Math.round(n * 1e6) / 1e6;
const rows = $input.all().map((i) => i.json).filter((r) => r.status);
const others = round(rows
  .filter((r) => r.id !== mine.id && r.status !== 'released' && !(r.status === 'reserved' && r.id > mine.id))
  .reduce((sum, r) => sum + (Number(r.amount) || 0), 0));
const fits = others + c.reservation <= c.budget;

return [{
  json: {
    ...c,
    row_id: mine.id,
    used_by_others: others,
    fits,
    http_status: fits ? 200 : 429,
    error: fits ? null : 'budget_reached',
    message: fits ? null : 'Parallel runs used the remaining budget first. Try again later.',
  },
}];

// Books what the run actually used. Token counts come from n8n's own record of every call the
// "Chat model" node made, read through the n8n API (see "Read token usage").
const MODEL_NODE = 'Chat model'; // update these two names if you rename the nodes
const AGENT_NODE = 'Client AI agent';
const s = $('Settings').first().json;
const c = $('Confirm reservation').first().json;
const ex = $input.first().json ?? {};

const round = (n) => Math.round(n * 1e6) / 1e6;
const rateIn = Number(s.input_cost_per_1m_tokens) || 0;
const rateOut = Number(s.output_cost_per_1m_tokens) || 0;
const amountFor = (i, o) => round(rateIn > 0 || rateOut > 0 ? (i * rateIn + o * rateOut) / 1e6 : i + o);

// Output 0 of the agent = success, output 1 = error (On Error: continue using error output).
let succeeded = false;
let answer = '';
let failure = '';
try {
  const ok = $(AGENT_NODE).all(0);
  if (ok.length) { succeeded = true; answer = String(ok[0].json.output ?? ''); }
} catch (e) {}
if (!succeeded) {
  try {
    const bad = $(AGENT_NODE).all(1);
    const err = bad[0]?.json?.error;
    failure = String(err?.message ?? err ?? 'The agent failed');
  } catch (e) {
    failure = 'The agent failed';
  }
}

// The agent's own entry proves that n8n saved this execution's progress. Without it, the record is incomplete.
const runData = ex.data?.resultData?.runData;
let readable = !!runData?.[AGENT_NODE];
let tokensIn = 0, tokensOut = 0, calls = 0, estimated = false;
for (const run of (runData?.[MODEL_NODE] ?? [])) {
  const out = run?.data?.ai_languageModel?.[0]?.[0]?.json;
  if (!out || (!out.tokenUsage && !out.tokenUsageEstimate)) continue; // failed calls carry no usage
  calls++;
  if (!out.tokenUsage) estimated = true;
  const u = out.tokenUsage ?? out.tokenUsageEstimate ?? {};
  tokensIn += Number(u.promptTokens) || 0;
  tokensOut += Number(u.completionTokens) || 0;
}

if (succeeded && calls === 0) readable = false; // an answer without a recorded model call means the record is incomplete

let amount;
let measured;
if (readable) {
  amount = amountFor(tokensIn, tokensOut);
  measured = calls === 0 ? 'no usage recorded' : estimated ? 'n8n estimate (provider sent no usage)' : 'reported by provider';
} else {
  amount = c.reservation; // safe side: charge the whole reservation
  measured = 'usage not readable, charged the full reservation';
}

const status = !succeeded && amount === 0 ? 'released' : 'settled';
const usedAfter = round(c.used_by_others + amount);
const pct = Number(s.alert_at_percent) || 0;
const threshold = (c.budget * pct) / 100;
// Two alerts: the client crossed alert_at_percent, or what is left no longer covers another run like this one.
const crossed = pct > 0 && c.used_by_others < threshold && usedAfter >= threshold;
const exhausted = usedAfter + c.reservation > c.budget;
const usage = {
  this_run: amount,
  tokens_in: tokensIn,
  tokens_out: tokensOut,
  model_calls: calls,
  measured,
  used: usedAfter,
  budget: c.budget,
  remaining: Math.max(round(c.budget - usedAfter), 0),
  unit: c.unit,
  period: c.period,
};

return [{
  json: {
    row_id: c.row_id,
    succeeded,
    update: {
      status,
      amount,
      tokens_in: tokensIn,
      tokens_out: tokensOut,
      model_calls: calls,
      note: (succeeded ? measured : `Agent failed: ${failure}`).slice(0, 500),
    },
    response: succeeded
      ? { client_id: c.client_id, answer, usage }
      : { error: 'agent_failed', message: failure, client_id: c.client_id, usage },
    alert: {
      send: crossed || exhausted,
      kind: exhausted ? 'exhausted' : 'threshold',
      client_id: c.client_id,
      period: c.period,
      used: usedAfter,
      budget: c.budget,
      unit: c.unit,
      percent: c.budget > 0 ? Math.round((usedAfter / c.budget) * 100) : 100,
    },
  },
}];

// Reservations older than the TTL belong to runs that crashed or timed out.
// They are marked "expired" and keep counting, so the budget errs on the safe side.
const ttl = Number($('Sweep settings').first().json.reservation_ttl_minutes) || 30;
const cutoff = Date.now() - ttl * 60 * 1000;
return $input.all()
  .filter((i) => i.json.status === 'reserved' && new Date(i.json.createdAt).getTime() < cutoff)
  .map((i) => ({ json: { id: i.json.id, client_id: i.json.client_id, run_id: i.json.run_id, ttl } }));

// Totals per client for last month, for your records or invoicing, plus the cut-off for cleanup.
const s = $('Monthly settings').first().json;
const now = new Date();
const last = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1)).toISOString().slice(0, 7);
const keep = Math.max(Number(s.keep_months) || 6, 1);
const cutoff = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - keep, 1)).toISOString().slice(0, 7);

const round = (n) => Math.round(n * 1e6) / 1e6;
const rows = $input.all().map((i) => i.json).filter((r) => r.status && r.period === last);
const byClient = {};
for (const r of rows) {
  const t = (byClient[r.client_id] ??= { used: 0, runs: 0, expired: 0, tokens_in: 0, tokens_out: 0 });
  if (r.status !== 'released') t.used = round(t.used + (Number(r.amount) || 0));
  if (r.status === 'settled') t.runs++;
  if (r.status === 'expired') t.expired++;
  t.tokens_in += Number(r.tokens_in) || 0;
  t.tokens_out += Number(r.tokens_out) || 0;
}
const lines = Object.entries(byClient)
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([id, t]) => `${id}: used ${t.used} | runs ${t.runs} | tokens in ${t.tokens_in}, out ${t.tokens_out}` + (t.expired ? ` | ${t.expired} expired reservation(s) to review` : ''));

return [{
  json: {
    period: last,
    cutoff,
    subject: `AI usage per client for ${last}`,
    text: (lines.length ? lines.join('\n') : `No AI usage was recorded for ${last}.`) +
      `\n\nAmounts are in the same unit as monthly_budget. Ledger rows from before ${cutoff} are deleted after this email.`,
  },
}];

// Usage per client for one month (?period=YYYY-MM, default: this month; optional ?client_id=).
const q = $('Usage request').first().json.query ?? {};
const period = /^\d{4}-\d{2}$/.test(q.period ?? '') ? q.period : new Date().toISOString().slice(0, 7);
const clients = $('Load clients').all().map((i) => i.json).filter((c) => c.client_id);
const rows = $input.all().map((i) => i.json).filter((r) => r.status && r.period === period);
const round = (n) => Math.round(n * 1e6) / 1e6;

const out = clients
  .filter((c) => !q.client_id || c.client_id === q.client_id)
  .map((c) => {
    const mine = rows.filter((r) => r.client_id === c.client_id);
    const sum = (st) => round(mine.filter((r) => r.status === st).reduce((a, r) => a + (Number(r.amount) || 0), 0));
    const settled = sum('settled');
    const reserved = sum('reserved');
    const expired = sum('expired');
    const used = round(settled + reserved + expired);
    const budget = Number(c.monthly_budget);
    return {
      client_id: c.client_id,
      paused: c.paused === true || String(c.paused).toLowerCase() === 'true',
      budget,
      used,
      settled,
      reserved_now: reserved,
      expired,
      percent: budget > 0 ? Math.round((used / budget) * 100) : null,
      remaining: Number.isFinite(budget) ? Math.max(round(budget - used), 0) : null,
      runs_booked: mine.filter((r) => r.status === 'settled').length,
      refused_after_reserving: mine.filter((r) => r.status === 'released').length,
    };
  });

return [{ json: { period, clients: out } }];
